function firstFailure(steps) {
  for (const s of steps) {
    if (!s.passed) return s.name;
  }
  return null;
}

function bypassedFailures(steps) {
  return steps.filter((s) => !s.passed && s.bypass).map((s) => s.name);
}

function passedNames(steps) {
  return steps.filter((s) => s.passed).map((s) => s.name);
}

function stoppedAt(steps) {
  for (const s of steps) {
    if (!s.passed && !s.bypass) return s.name;
  }
  return null;
}

function stepsRun(steps) {
  const ran = [];
  for (const s of steps) {
    ran.push(s.name);
    if (!s.passed && !s.bypass) break;
  }
  return ran;
}

function hiddenFailures(steps) {
  const hidden = [];
  for (const s of steps) {
    if (!s.passed && s.bypass) hidden.push(s.name);
    if (!s.passed && !s.bypass) break;
  }
  return hidden;
}
